insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values
  ('fcd0632e-ac0a-566a-a385-fec9e4b1e664', 'Horários só saem em notícias de jornal, não em página da catedral ou da arquidiocese. Instagram visto em trecho de notícia. Ponto no mapa aproximado: centro da cidade.', '{"https://www.aves.org.br/paroquias/nossa-senhora-da-vitoria/"}', ''),
  ('35e3648b-6a28-5747-bea6-c8512aafef4f', 'Padroeiro da cidade de Vitória; aos cuidados dos padres pavonianos. Ponto no mapa aproximado: centro da cidade.', '{"https://basilicadesantoantonio.com.br/missas/","https://basilicadesantoantonio.com.br/confissoes/","https://www.aves.org.br/paroquias/basilica-de-santo-antonio/"}', 'alta'),
  ('b603189d-e80c-5d38-b9ff-396a860d0b95', 'Sem horário publicado pela paróquia ou pela arquidiocese; a página da paróquia no site da arquidiocese traz só contatos e endereço. Ponto no mapa aproximado: centro da cidade.', '{"https://www.aves.org.br/paroquias/sagrada-familia-2/"}', ''),
  ('195414e7-b862-557b-8ff2-67e0bded53ab', 'Sem horário publicado pela paróquia ou pela arquidiocese; a página da paróquia no site da arquidiocese traz só contatos e endereço.', '{"https://www.aves.org.br/paroquias/ressurreicao/"}', ''),
  ('ae8bd08e-d9b8-544a-97ab-469eac7ed3a2', 'Sem horário publicado; o site próprio (psaopedro.org.br) estava fora do ar na pesquisa.', '{"https://www.aves.org.br/paroquias/sao-pedro-4/"}', ''),
  ('ae8bd08e-d9b8-544a-97ab-469eac7ed3a2', 'Sem horário publicado pela paróquia ou pela arquidiocese; a página da paróquia no site da arquidiocese traz só contatos e endereço.', '{"https://www.aves.org.br/paroquias/sao-pedro-3/"}', ''),
  ('338aa124-62d3-5dcf-97c7-fff84c69f244', 'Sem horário fixo publicado: a página da paróquia no site da arquidiocese traz só uma agenda de maio de 2021. Fica na região da Grande São Pedro. Ponto no mapa aproximado: centro da cidade.', '{"https://www.aves.org.br/paroquias/sao-pedro-apostolo/"}', ''),
  ('86634b77-8764-5013-a8a0-907d62fc8768', 'O site próprio tem página de missas, mas o conteúdo não carrega sem navegador (Wix); sem horário confirmado. Ponto no mapa aproximado: centro da cidade.', '{"https://www.aves.org.br/paroquias/sao-francisco-de-assis-5/"}', ''),
  ('2579c2c8-5af2-55f1-9aab-bdc2b695e59f', 'A página de horários no site da arquidiocese (2021) está vazia; sem horário confirmado.', '{"https://www.aves.org.br/paroquias/nossa-senhora-das-gracas-2/"}', ''),
  ('8989af64-1559-5f1f-b16e-fc9458b308a7', 'Sem horário publicado pela paróquia ou pela arquidiocese; a página da paróquia no site da arquidiocese traz só contatos e endereço.', '{"https://www.aves.org.br/paroquias/santa-luzia-2/"}', ''),
  ('1d46a467-2d99-5542-8bef-fb8c1c6a0bb6', 'Sem horário publicado pela paróquia ou pela arquidiocese; a página da paróquia no site da arquidiocese traz só contatos e endereço.', '{"https://www.aves.org.br/paroquias/santa-rita-de-cassia-2/"}', ''),
  ('7ce452cb-d39e-582e-bf89-cebe615491ee', 'Sem horário publicado pela paróquia ou pela arquidiocese; a página da paróquia no site da arquidiocese traz só contatos e endereço. Ponto no mapa aproximado: centro da cidade.', '{"https://www.aves.org.br/paroquias/santa-teresa-de-calcuta/"}', ''),
  ('051f1e2a-a416-5af0-91ad-85787216ab18', 'Só o horário de confissões foi publicado (site da arquidiocese, 2021); missas sem fonte.', '{"https://www.aves.org.br/atendimento-na-paroquia-4/","https://www.aves.org.br/paroquias/sao-camilo-de-lellis/"}', 'alta'),
  ('6828d86e-4279-5650-aac8-b1f1f339c0be', 'Sem horário publicado pela paróquia ou pela arquidiocese; a página da paróquia no site da arquidiocese traz só contatos e endereço.', '{"https://www.aves.org.br/paroquias/sao-jose-3/"}', ''),
  ('c3d3e209-6fc5-5812-80ee-6e3d880e2be9', 'Convento da Penha, aos cuidados dos franciscanos; principal santuário do Espírito Santo, não é paróquia. Missas na capela do convento e no Campinho. Fora do formato: Confissões por ordem de chegada, podem encerrar antes', '{"https://conventodapenha.org.br/horarios-de-missas/","https://www.aves.org.br/paroquias/convento-nossa-senhora-da-penha/"}', 'alta'),
  ('59d1acb0-adca-522f-a7cd-1887d9d953b9', 'Aos cuidados dos franciscanos; a matriz, na Prainha, é a igreja mais antiga do ES. Secretaria na Rua Cabo Aylson Simões, 762, Centro. O site lista ainda 8 comunidades com missa de domingo, sem o endereço de cada uma. Ponto no mapa aproximado: centro da cidade.', '{"https://paroquiadorosario.com/horarios-de-missa/","https://www.aves.org.br/paroquias/nossa-senhora-do-rosario/"}', 'alta'),
  ('8818aba4-0152-54b4-9f6a-6f09425ab16a', 'Ponto no mapa aproximado: centro da cidade.', '{"https://bompastorpraia.com.br/","https://www.aves.org.br/paroquias/bom-pastor-3/"}', 'alta'),
  ('b16f0e43-c785-539b-b558-a08dc8b4ee37', 'O site próprio publica as missas só num calendário dinâmico, sem quadro fixo; sem horário confirmado.', '{"https://www.aves.org.br/paroquias/nossa-senhora-do-perpetuo-socorro/"}', ''),
  ('b834373e-6ea5-5840-8e89-02f790c0dec9', 'A página de horários no site da arquidiocese (2021) está vazia; sem horário confirmado. Bairro visto em trecho de notícia. Ponto no mapa aproximado: centro da cidade.', '{"https://www.aves.org.br/atendimento-na-paroquia-3/","https://www.aves.org.br/paroquias/nossasenhoraaparecida/"}', ''),
